const hasIntl = typeof Intl === 'object' && !!Intl
const Collator = hasIntl && Intl.Collator
const cache = new Map()

const collatorCompare = (locale, opts) => {
  const collator = new Collator(locale, opts)
  return (a, b) => collator.compare(a, b)
