const timers = new Map()
const finished = new Map()

process.on('time', (level, name) => {
  if (level === 'start') {
    if (timers.has(name)) {
      throw new Error('conflicting timer! ' + name)
    }
    timers.set(name, process.hrtime.bigint())
  } else if (level === 'end') {
    if (!timers.has(name)) {
      throw new Error('timer not started! ' + name)
